WITH recent_products AS (SELECT * FROM products WHERE SIZE(tags) > 1 AND ARRAY_CONTAINS(tags, 'sale') AND launch_date BETWEEN '2024-06-01' AND '2025-10-16'), ProductsStats AS (SELECT category, COUNT(DISTINCT cost) AS unique_categorys, AVG(stock_qty) AS avg_stock_qty FROM recent_products GROUP BY category) SELECT category, unique_categorys, avg_stock_qty FROM ProductsStats ORDER BY unique_categorys DESC
